result:
    .goods-box{
		padding: 0 15px;
		.wrapper,.list-group{
			display: flex
			flex-wrap: wrap
			width: 272px;
		}
		.title{
			color: #999999;
			font-size: 12px;
			width: 75px;
			margin-right: 16px;
			margin-top: 20px;
		}
		.add-item{
			display: flex
			align-items: center
			justify-content: center
			border-radius: 4px;
			border: 1px solid #eee;
			.iconfont-diy{
				font-size: 24px
				color: #D8D8D8
			}
		}
		.item{
			position: relative
			width: 64px
			height: 64px
			margin-bottom: 20px
			margin-right: 12px
			&:nth-of-type(3n){
				margin-right: 0;
			}
			img {
				width: 100%
				height: 100%
			}
			.icondel_1{
				position: absolute
				right: -5px
				top: -12px
				color: #999999
				font-size: 22px
				cursor: pointer
			}
		}
	}
